using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
namespace Orbit {
 public sealed class MinecraftSettings {public int schema=1;public string prismExe="",prismRoot="",curseRoot="",packFolder="",radminExe="";public bool askRadmin=true;}
 public sealed class MinecraftProfile {public string id,name,source,version,loader,loaderVersion,instanceId,path,gamePath;public bool launchable;}
 public sealed class MinecraftPack {public string id,name,format,version,path;public long bytes;}
 public sealed class MinecraftMod {public string file;public long bytes;public bool enabled;}
 public sealed class MinecraftScan {public List<MinecraftProfile> profiles=new List<MinecraftProfile>();public List<MinecraftPack> packs=new List<MinecraftPack>();public List<string>warnings=new List<string>();}
 public sealed class MinecraftException:Exception {public string Code{get;}public MinecraftException(string code):base("Minecraft operation failed"){Code=code;}}
 public static class MinecraftFiles {
  public static void ValidateSettings(MinecraftSettings s){if(s==null||s.schema!=1)throw new MinecraftException("settings");foreach(var p in new[]{s.prismExe,s.prismRoot,s.curseRoot,s.packFolder,s.radminExe})if(p==null||p.Length>1000||p.Any(char.IsControl)||p.Length>0&&!Path.IsPathRooted(p))throw new MinecraftException("settings");}
  public static string Key(string kind,string path){using(var h=SHA256.Create())return kind+BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar).ToUpperInvariant()))).Replace("-","").ToLowerInvariant();}
  static bool Link(string path)=>(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0;
  static void DirectorySafe(string path){if(!Directory.Exists(path)||Link(path))throw new MinecraftException("missing");}
  static JObject Json(string file,int max=2*1024*1024){if(new FileInfo(file).Length>max)throw new MinecraftException("invalid");using(var r=new JsonTextReader(new StreamReader(file)){MaxDepth=24}){var j=JObject.Load(r);if(r.Read())throw new MinecraftException("invalid");return j;}}
  public static Dictionary<string,string> Ini(string file){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(!File.Exists(file))return d;if(new FileInfo(file).Length>512*1024)throw new MinecraftException("invalid");bool general=true;foreach(var raw in File.ReadLines(file)){var line=raw.Trim();if(line.StartsWith("[")){general=line=="[General]";continue;}int i=line.IndexOf('=');if(general&&i>0)d[line.Substring(0,i).Trim()]=line.Substring(i+1).Trim().Trim('"').Replace("\\\\","\\");}return d;}
  public static string InstancesRoot(string root){var cfg=Ini(Path.Combine(root,"prismlauncher.cfg"));string custom;return Path.GetFullPath(cfg.TryGetValue("InstanceDir",out custom)&&custom.Length>0?Path.IsPathRooted(custom)?custom:Path.Combine(root,custom):Path.Combine(root,"instances"));}
  public static string GameRoot(string instance){string regular=Path.Combine(instance,"minecraft"),dot=Path.Combine(instance,".minecraft");return Directory.Exists(dot)&&!Directory.Exists(regular)?dot:regular;}
  public static MinecraftProfile PrismProfile(string folder){DirectorySafe(folder);if(!File.Exists(Path.Combine(folder,"instance.cfg")))throw new MinecraftException("invalid");var cfg=Ini(Path.Combine(folder,"instance.cfg"));var j=Json(Path.Combine(folder,"mmc-pack.json"));var components=j["components"] as JArray;if(components==null)throw new MinecraftException("invalid");var v=components.OfType<JObject>().FirstOrDefault(c=>(string)c["uid"]=="net.minecraft");string name;var p=new MinecraftProfile{id=Key("prism-",folder),source="prism",name=cfg.TryGetValue("name",out name)?name:Path.GetFileName(folder),version=(string)v?["version"]??"",loader="Vanilla",loaderVersion="",instanceId=Path.GetFileName(folder),path=folder,gamePath=GameRoot(folder)};
   foreach(var c in components.OfType<JObject>()){var uid=(string)c["uid"];string loader=uid=="net.minecraftforge"?"Forge":uid=="net.neoforged"?"NeoForge":uid=="net.fabricmc.fabric-loader"?"Fabric":uid=="org.quiltmc.quilt-loader"?"Quilt":null;if(loader!=null){p.loader=loader;p.loaderVersion=(string)c["version"]??"";}}p.launchable=p.version.Length>0;return p;
  }
  public static MinecraftProfile CurseProfile(string folder){DirectorySafe(folder);var file=Path.Combine(folder,"minecraftinstance.json");if(new FileInfo(file).Length>32*1024*1024)throw new MinecraftException("invalid");string name=null,version=null,loader=null;
   using(var r=new JsonTextReader(new StreamReader(file)){MaxDepth=40}){if(!r.Read()||r.TokenType!=JsonToken.StartObject)throw new MinecraftException("invalid");while(r.Read()){if(r.TokenType==JsonToken.EndObject)break;if(r.TokenType!=JsonToken.PropertyName)throw new MinecraftException("invalid");string key=(string)r.Value;if(!r.Read())throw new MinecraftException("invalid");if(key=="name")name=r.Value as string;else if(key=="gameVersion")version=r.Value as string;else if(key=="baseModLoader"&&r.TokenType==JsonToken.StartObject){var l=JObject.Load(r);loader=(string)l["name"];version=version??(string)l["minecraftVersion"]??(string)l["gameVersion"];}else r.Skip();}}
   if(string.IsNullOrWhiteSpace(name))name=Path.GetFileName(folder);return new MinecraftProfile{id=Key("curse-",folder),source="curseforge",name=name,version=version??"",loader=loader??"Vanilla",loaderVersion="",instanceId=Path.GetFileName(folder),path=folder,gamePath=folder,launchable=false};
  }
  public static MinecraftScan Scan(MinecraftSettings settings){var result=new MinecraftScan();foreach(var source in new[]{"prism","curseforge"}){var root=source=="prism"?settings.prismRoot:settings.curseRoot;if(string.IsNullOrEmpty(root))continue;try{root=source=="prism"?InstancesRoot(root):Directory.Exists(Path.Combine(root,"Instances"))?Path.Combine(root,"Instances"):root;if(!Directory.Exists(root))continue;foreach(var dir in Directory.EnumerateDirectories(root).Take(501)){if(result.profiles.Count>=500){result.warnings.Add("Показаны первые 500 сборок.");break;}try{if(Link(dir))continue;var required=Path.Combine(dir,source=="prism"?"mmc-pack.json":"minecraftinstance.json");if(!File.Exists(required))continue;result.profiles.Add(source=="prism"?PrismProfile(dir):CurseProfile(dir));}catch{result.warnings.Add("Одну из сборок не удалось прочитать. Проверь её в исходном лаунчере.");}}}catch{result.warnings.Add("Папка сборок недоступна. Проверь пути в настройках Minecraft.");}}
   if(!string.IsNullOrEmpty(settings.packFolder)){try{if(Directory.Exists(settings.packFolder)){foreach(var file in Directory.EnumerateFiles(settings.packFolder).Where(p=>new[]{".zip",".mrpack"}.Contains(Path.GetExtension(p).ToLowerInvariant())).Take(200)){try{if(!Link(file))result.packs.Add(Pack(file));}catch{/* A download may still be incomplete. Recheck next scan. */}}}}catch{result.warnings.Add("Папка модпаков недоступна.");}}
   result.profiles=result.profiles.OrderBy(p=>p.name,StringComparer.CurrentCultureIgnoreCase).ToList();result.warnings=result.warnings.Distinct().ToList();return result;
  }
  public static string ModsRoot(MinecraftProfile p){DirectorySafe(p.path);string expected=p.source=="prism"?GameRoot(p.path):p.path;if(Path.GetFullPath(p.gamePath)!=Path.GetFullPath(expected))throw new MinecraftException("invalid");if(Directory.Exists(expected)&&Link(expected))throw new MinecraftException("unsafe");var mods=Path.Combine(expected,"mods");if(Directory.Exists(mods)&&Link(mods))throw new MinecraftException("unsafe");return mods;}
  public static List<MinecraftMod> Mods(MinecraftProfile p){var root=ModsRoot(p);if(!Directory.Exists(root))return new List<MinecraftMod>();return Directory.EnumerateFiles(root).Where(f=>(f.EndsWith(".jar",StringComparison.OrdinalIgnoreCase)||f.EndsWith(".jar.disabled",StringComparison.OrdinalIgnoreCase))&&!Link(f)).Take(3000).Select(f=>new MinecraftMod{file=Path.GetFileName(f),bytes=new FileInfo(f).Length,enabled=f.EndsWith(".jar",StringComparison.OrdinalIgnoreCase)}).OrderBy(m=>m.file,StringComparer.CurrentCultureIgnoreCase).ToList();}
  public static MinecraftPack Pack(string file){var info=new FileInfo(file);if(!info.Exists||Link(file)||info.Length>4L*1024*1024*1024)throw new MinecraftException("pack");using(var z=ZipFile.OpenRead(file)){if(z.Entries.Count>30000)throw new MinecraftException("pack");long total=0;foreach(var e in z.Entries){var name=e.FullName.Replace('\\','/');if(name.StartsWith("/")||name.Contains(":")||name.Split('/').Any(s=>s==".."||s=="."))throw new MinecraftException("pack");total=checked(total+e.Length);if(total>8L*1024*1024*1024)throw new MinecraftException("pack");}
    var entry=z.GetEntry("modrinth.index.json")??z.GetEntry("manifest.json")??z.Entries.FirstOrDefault(e=>e.Name=="mmc-pack.json"&&e.FullName.Count(c=>c=='/')<=1);if(entry==null||entry.Length>2*1024*1024)throw new MinecraftException("pack");JObject j;using(var r=new JsonTextReader(new StreamReader(entry.Open())){MaxDepth=24})j=JObject.Load(r);
    string format,version;if(entry.Name=="modrinth.index.json"&&(string)j["game"]=="minecraft"&&j["files"] is JArray){format="Modrinth";version=(string)j["dependencies"]?["minecraft"];}else if(entry.Name=="manifest.json"&&j["minecraft"] is JObject&&j["files"] is JArray){format="CurseForge";version=(string)j["minecraft"]?["version"];}else if(entry.Name=="mmc-pack.json"&&j["components"] is JArray){format="Prism";version="";}else throw new MinecraftException("pack");return new MinecraftPack{id=Key("pack-",file),name=(string)j["name"]??Path.GetFileNameWithoutExtension(file),version=version??"",format=format,path=file,bytes=info.Length};}}
  public static void CheckMod(string file){if(!File.Exists(file)||Link(file)||!file.EndsWith(".jar",StringComparison.OrdinalIgnoreCase)||new FileInfo(file).Length>512L*1024*1024)throw new MinecraftException("mod");using(var z=ZipFile.OpenRead(file)){if(z.Entries.Count>100000||!new[]{"fabric.mod.json","quilt.mod.json","META-INF/mods.toml","META-INF/neoforge.mods.toml","mcmod.info"}.Any(s=>z.GetEntry(s)!=null))throw new MinecraftException("mod");}}
  static byte[] Hash(string f){using(var h=SHA256.Create())using(var s=File.OpenRead(f))return h.ComputeHash(s);}
  public static void AddMods(MinecraftProfile p,string[] sources){if(p.loader=="Vanilla")throw new MinecraftException("loader");if(sources==null||sources.Length==0||sources.Length>100)throw new MinecraftException("mod");var root=ModsRoot(p);var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long sum=0;foreach(var f in sources){CheckMod(f);sum+=new FileInfo(f).Length;var n=Path.GetFileName(f);if(!names.Add(n)||File.Exists(Path.Combine(root,n))||File.Exists(Path.Combine(root,n+".disabled")))throw new MinecraftException("exists");}if(sum>2L*1024*1024*1024)throw new MinecraftException("mod");
   Directory.CreateDirectory(root);var staging=Path.Combine(root,".orbit-import-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);var added=new Dictionary<string,byte[]>();try{foreach(var f in sources){var stage=Path.Combine(staging,Path.GetFileName(f));File.Copy(f,stage);CheckMod(stage);}foreach(var f in sources){var stage=Path.Combine(staging,Path.GetFileName(f));var dest=Path.Combine(root,Path.GetFileName(f));var hash=Hash(stage);File.Move(stage,dest);added[dest]=hash;}}catch{foreach(var kv in added)try{if(File.Exists(kv.Key)&&Hash(kv.Key).SequenceEqual(kv.Value))File.Delete(kv.Key);}catch{}throw;}finally{try{Directory.Delete(staging,true);}catch{}}
  }
  public static void ToggleMod(MinecraftProfile p,string filename){if(string.IsNullOrEmpty(filename)||filename!=Path.GetFileName(filename)||filename.Contains('/')||filename.Contains('\\')||!Mods(p).Any(m=>m.file==filename))throw new MinecraftException("missing");var root=ModsRoot(p);var old=Path.Combine(root,filename);var dest=filename.EndsWith(".disabled",StringComparison.OrdinalIgnoreCase)?old.Substring(0,old.Length-9):old+".disabled";if(File.Exists(dest))throw new MinecraftException("exists");File.Move(old,dest);}
  public static string Quote(string value){if(value==null||value.Any(char.IsControl))throw new MinecraftException("invalid");var s=new StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='"'){s.Append('\\',slashes*2+1).Append(c);slashes=0;continue;}s.Append('\\',slashes).Append(c);slashes=0;}return s.Append('\\',slashes*2).Append('"').ToString();}
  public static string PrismArguments(string root,string action=null,string value=null){if(string.IsNullOrWhiteSpace(root)||!Path.IsPathRooted(root))throw new MinecraftException("settings");var args=Quote("--dir="+root);if(action!=null){if(!new[]{"launch","show","import"}.Contains(action)||string.IsNullOrEmpty(value))throw new MinecraftException("invalid");if(action!="import"&&(value!=Path.GetFileName(value)||value.Contains('\\')||value.Contains('/')))throw new MinecraftException("invalid");args+=" "+Quote("--"+action+"="+value);}return args;}
 }
}
